'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { Game } = require('../dist/game.js');
const Checkpoint = require('../dist/checkpoint.js');
const legacy = require('./fixtures/v5-checkpoint.json');

// Generated by executing game.js and navigation.js from the actual v5 commit
// 4d9257519eedee954dcfb35b85b5ba76cff8fd82, not by relabelling a v6 export.
// The fixture contains a focus, a basic attack in flight, six future R impacts,
// a deliberate move destination, a bought bow and the 18-second wave boundary.
const DT = 1 / 60;
const clone = value => JSON.parse(JSON.stringify(value));
const playerOf = saved => saved.state.entities.find(entity => entity.id === 'player');
function storage(initial = null) {
  let raw = initial;
  return {
    writes: 0, removals: 0, failWrite: false,
    getItem(key) { assert.equal(key, Checkpoint.KEY); return raw; },
    setItem(key, value) {
      assert.equal(key, Checkpoint.KEY);
      if (this.failWrite) throw new Error('QuotaExceededError');
      this.writes++; raw = value;
    },
    removeItem(key) { assert.equal(key, Checkpoint.KEY); this.removals++; raw = null; },
    raw() { return raw; }
  };
}
function runningCopy(game) {
  return Game.fromState(clone(game.exportState()), { paused: false, clearInput: false });
}
function sameContinuation(game, copy, seconds) {
  assert.deepEqual(copy.exportState(), game.exportState());
  for (let i = 0; i < Math.ceil(seconds / DT); i++) { game.step(DT); copy.step(DT); }
  assert.deepEqual(copy.exportState(), game.exportState(), 'Every serialized rule state follows the same continuation');
}
function windingGame() {
  const game = new Game({ hero: 'ranger', seed: 321 });
  game.start();
  const target = game.entities.find(entity => entity.type === 'hero' && entity.team === 1);
  for (const entity of game.entities) if (entity !== game.player && ['hero', 'minion'].includes(entity.type)) entity.stunnedUntil = 1000;
  Object.assign(game.player, { x: 800, y: 800, autoAttack: false, nextAttackBonus: 75 });
  Object.assign(target, { x: 1020, y: 800 });
  game._rebuildIndex();
  assert.equal(game.attackTarget(target.id).ok, true);
  for (let i = 0; i < 6; i++) game.step(DT);
  assert.equal(game.getAttackState().phase, 'windup');
  assert.ok(game.player.attackWindup.remaining > 0 && game.player.attackWindup.remaining < game.player.attackWindup.duration);
  assert.equal(game.projectiles.filter(shot => shot.sourceId === 'player').length, 0);
  return { game, target };
}

test('authentic v5 migration preserves focus, live projectiles, planned movement and journey metadata', () => {
  assert.equal(legacy.state.engineVersion, 5);
  const oldPlayer = playerOf(legacy.state);
  assert.equal(Object.hasOwn(oldPlayer, 'attackWindup'), false);
  assert.equal(Object.hasOwn(oldPlayer, 'attackPeriod'), false);
  const target = storage(JSON.stringify(legacy));
  const read = Checkpoint.read(target);
  assert.equal(read.status, 'ready', read.reason);
  const restored = Checkpoint.restore(read.checkpoint);
  assert.equal(restored.ok, true, restored.reason);
  const game = restored.game;
  assert.equal(game.paused, true);
  assert.equal(game.time, legacy.state.state.time);
  assert.equal(game.getFocusTarget().id, legacy.state.state._focusTargetId);
  assert.deepEqual(game._moveDestination, legacy.state.state._moveDestination);
  assert.deepEqual(restored.ui, legacy.ui);
  for (const field of ['hero', 'level', 'gold', 'hp', 'mana', 'attackCooldown']) assert.equal(game.player[field], oldPlayer[field], field);
  for (const field of ['inventory', 'skillRanks', 'cd']) assert.deepEqual(game.player[field], oldPlayer[field], field);
  for (const hero of game.entities.filter(entity => entity.type === 'hero')) {
    assert.equal(hero.attackWindup, null, 'Old completed attacks must never become a new pending release');
    assert.ok(Number.isFinite(hero.attackPeriod) && hero.attackPeriod > 0);
  }
  const shot = game.projectiles.find(projectile => projectile.sourceId === 'player' && projectile.homing);
  assert.ok(shot);
  assert.equal(shot.source, game.player);
  assert.equal(game._pending.filter(action => action.source === game.player).length, 6);
  assert.equal(target.writes, 0);
  assert.equal(target.removals, 0);
  assert.equal(Checkpoint.write(target, game, restored.ui, legacy.savedAt + 1000).ok, true);
  const upgraded = JSON.parse(target.raw());
  assert.equal(upgraded.state.engineVersion, 6);
  assert.deepEqual(upgraded.ui, legacy.ui);
  assert.equal(Checkpoint.read(target).status, 'ready');
});

test('migrating a v5 in-flight attack and saving again gives identical current-engine continuation', () => {
  const game = Game.fromState(clone(legacy.state), { paused: false, clearInput: false });
  const wave = game.waveNumber;
  const shotId = game.projectiles.find(projectile => projectile.sourceId === 'player' && projectile.homing).id;
  sameContinuation(game, runningCopy(game), 4);
  assert.ok(game.waveNumber > wave);
  assert.equal(game.projectiles.some(projectile => projectile.id === shotId), false);
  assert.equal(game._pending.some(action => action.sourceId === 'player'), false);
});

test('a paused v6 windup freezes, resumes its remainder and releases exactly one empowered basic attack', () => {
  const { game, target } = windingGame();
  const attack = clone(game.getAttackState());
  const saved = clone(game.exportState());
  assert.equal(saved.engineVersion, 6);
  const resumed = Game.fromState(saved);
  const expectedDamage = game._damageValue(target, game._basicAttackDamage(game.player, target), game.player, 'physical');
  const damageBefore = game.player.damageDealt;
  assert.deepEqual(resumed.getAttackState(), attack);
  resumed.step(5);
  assert.deepEqual(resumed.getAttackState(), attack, 'The continue screen must not count down the saved windup');
  assert.equal(resumed.time, game.time);
  resumed.paused = false;
  assert.deepEqual(resumed.exportState(), game.exportState());
  for (let i = 0; i < Math.ceil(attack.remaining / DT) + 1; i++) {
    game.step(DT); resumed.step(DT);
  }
  assert.deepEqual(resumed.exportState(), game.exportState());
  assert.equal(game.getAttackState().phase, 'recovery');
  assert.equal(game.player.attackWindup, null);
  const releases = game.projectiles.filter(shot => shot.sourceId === 'player' && shot.kind === 'basic');
  assert.equal(releases.length, 1);
  assert.equal(game.player.nextAttackBonus, 0, 'The saved bonus is consumed by the one release');
  game.stop(); resumed.stop();
  sameContinuation(game, resumed, 0.8);
  assert.ok(Math.abs(game.player.damageDealt - damageBefore - expectedDamage) < 1e-8, 'The projectile applies one empowered hit after restore');
  assert.equal(game.projectiles.some(shot => shot.sourceId === 'player'), false);
});

test('movement-canceled windup remains canceled after save and keeps the unspent attack bonus', () => {
  const { game } = windingGame();
  assert.equal(game.commandMove(730, 800).ok, true);
  assert.equal(game.player.attackWindup, null);
  const damageBefore = game.player.damageDealt;
  const copy = runningCopy(game);
  sameContinuation(game, copy, 1.2);
  assert.equal(game.player.nextAttackBonus, 75);
  assert.equal(game.player.damageDealt, damageBefore);
  assert.equal(game.projectiles.some(shot => shot.sourceId === 'player'), false);
});

test('v6 rejects malformed windup timers and target references without changing the previous save', () => {
  const { game } = windingGame();
  const saved = clone(game.exportState());
  const mutations = [
    value => { delete playerOf(value).attackWindup; },
    value => { delete playerOf(value).attackPeriod; },
    value => { playerOf(value).attackPeriod = 0; },
    value => { playerOf(value).attackPeriod = NaN; },
    value => { playerOf(value).attackWindup.remaining = -0.1; },
    value => { playerOf(value).attackWindup.remaining = playerOf(value).attackWindup.duration + 0.1; },
    value => { playerOf(value).attackWindup.duration = 0; },
    value => { playerOf(value).attackWindup.period = 0; },
    value => { playerOf(value).attackWindup.targetId = 'missing-target'; },
    value => { playerOf(value).attackWindup.targetId = 'player'; },
    value => { playerOf(value).attackWindup.targetId = 'nexus-0'; }
  ];
  for (const mutate of mutations) {
    const invalid = clone(saved);
    mutate(invalid);
    assert.throws(() => Game.fromState(invalid), /저장된 경기/, String(mutate));
    const raw = JSON.stringify({ version: 1, savedAt: 1, state: invalid, ui: { speed: 1 } });
    const target = storage(raw);
    assert.equal(Checkpoint.read(target).status, 'invalid', String(mutate));
    assert.equal(Checkpoint.restore(JSON.parse(raw)).ok, false, String(mutate));
    assert.equal(target.raw(), raw);
    assert.equal(target.writes, 0);
    assert.equal(target.removals, 0);
    const previous = storage(JSON.stringify(legacy));
    const previousRaw = previous.raw();
    const exporter = { started: true, over: false, exportState() { return clone(invalid); } };
    assert.equal(Checkpoint.write(previous, exporter, legacy.ui, legacy.savedAt + 1).ok, false, String(mutate));
    assert.equal(previous.raw(), previousRaw, 'Malformed new state must not replace the last restorable slot');
    assert.equal(previous.writes, 0);
    assert.equal(previous.removals, 0);
  }
  assert.deepEqual(game.exportState(), saved);
});

test('a failed v6 windup write preserves an authentic v5 slot until a successful atomic replacement', () => {
  const { game } = windingGame();
  const oldRaw = JSON.stringify(legacy);
  const target = storage(oldRaw);
  target.failWrite = true;
  assert.equal(Checkpoint.write(target, game, legacy.ui, legacy.savedAt + 1000).ok, false);
  assert.equal(target.raw(), oldRaw);
  assert.equal(target.writes, 0);
  assert.equal(target.removals, 0);
  assert.equal(Checkpoint.restore(Checkpoint.read(target).checkpoint).ok, true);
  target.failWrite = false;
  const saved = Checkpoint.write(target, game, legacy.ui, legacy.savedAt + 2000);
  assert.equal(saved.ok, true, saved.reason);
  assert.equal(target.writes, 1);
  assert.equal(target.removals, 0);
  const read = Checkpoint.read(target);
  assert.equal(read.status, 'ready', read.reason);
  const restored = Checkpoint.restore(read.checkpoint);
  assert.equal(restored.ok, true, restored.reason);
  assert.equal(restored.game.getAttackState().phase, 'windup');
  assert.equal(restored.game.player.nextAttackBonus, 75);
  assert.deepEqual(restored.ui, legacy.ui);
});
